import { Base, Point, typeCast, Type, markType, PointUtil } from "./type";
import { IVisualData, IVisualData_$type } from "./IVisualData";

/**
 * @hidden 
 */
export class PointData extends Base implements IVisualData {
	static $t: Type = markType(PointData, 'PointData', (<any>Base).$, [IVisualData_$type]);
	constructor(a: number, b: number) {
		super();
		this.x = a;
		this.y = b;
	}
	private _x: number = 0;
	get x(): number {
		return this._x;
	}
	set x(a: number) {
		this._x = a;
	}
	private _y: number = 0;
	get y(): number {
		return this._y;
	}
	set y(a: number) {
		this._y = a;
	}
	serialize(): string {
		return "{ x: " + this.x + ", y: " + this.y + "}";
	}
	static b(a: Point): PointData {
		let b: PointData = new PointData(a.x, a.y);
		return b;
	}
	g(): Point {
		let a: Point = PointUtil.create();
		a.x = this.x;
		a.y = this.y;
		return a;
	}
	equals(a: any): boolean {
		let b = typeCast<PointData>((<any>PointData).$, a);
		if (b == null) {
			return false;
		}
		return b.x == this.x && b.y == this.y;
	}
	getHashCode(): number {
		return ((this.x) * 397) ^ (this.y);
	}
	static get empty(): PointData {
		return new PointData(Number.POSITIVE_INFINITY, Number.POSITIVE_INFINITY);
	}
}


