import { Geometry } from "./Geometry";
import { Point, Base, Type, markType } from "./type";
import { GeometryType } from "./GeometryType";

/**
 * @hidden 
 */
export class EllipseGeometry extends Geometry {
	static $t: Type = markType(EllipseGeometry, 'EllipseGeometry', (<any>Geometry).$);
	e: Point = null;
	c: number = 0;
	d: number = 0;
	protected get_b(): GeometryType {
		return 3;
	}
	get b(): GeometryType {
		return this.get_b();
	}
}


