import { Base, Type, markType } from "./type";
import { CollisionGeometryType } from "./CollisionGeometryType";
import { CollisionRect } from "./CollisionRect";
import { Rect } from "./Rect";

/**
 * @hidden 
 */
export abstract class CollisionGeometry extends Base {
	static $t: Type = markType(CollisionGeometry, 'CollisionGeometry');
	abstract get type(): CollisionGeometryType;
	abstract get boundingBox(): CollisionRect;
	protected abstract d(a: CollisionRect): boolean;
	e(a: Rect): boolean {
		return this.collidesWith(new CollisionRect(0, a));
	}
	collidesWith(a: CollisionRect): boolean {
		if (!this.boundingBox.intersectsWith(a)) {
			return false;
		}
		return this.d(a);
	}
	collidesWithPoint(a: number, b: number): boolean {
		let c = new CollisionRect(1, a, b, 0, 0);
		if (!this.boundingBox.intersectsWith(c)) {
			return false;
		}
		return this.d(c);
	}
}


