import { Base, Type, markType } from "./type";

/**
 * @hidden 
 */
export class BreakEvenItem extends Base {
	static $t: Type = markType(BreakEvenItem, 'BreakEvenItem');
	private _FixedCost: number = 0;
	get FixedCost(): number {
		return this._FixedCost;
	}
	set FixedCost(a: number) {
		this._FixedCost = a;
	}
	private _VariableCost: number = 0;
	get VariableCost(): number {
		return this._VariableCost;
	}
	set VariableCost(a: number) {
		this._VariableCost = a;
	}
	private _SalesRevenue: number = 0;
	get SalesRevenue(): number {
		return this._SalesRevenue;
	}
	set SalesRevenue(a: number) {
		this._SalesRevenue = a;
	}
	private _MarginalProfit: number = 0;
	get MarginalProfit(): number {
		return this._MarginalProfit;
	}
	set MarginalProfit(a: number) {
		this._MarginalProfit = a;
	}
	private _Units: number = 0;
	get Units(): number {
		return this._Units;
	}
	set Units(a: number) {
		this._Units = a;
	}
	private _Ratio: number = 0;
	get Ratio(): number {
		return this._Ratio;
	}
	set Ratio(a: number) {
		this._Ratio = a;
	}
	get ActualProfit(): number {
		return this.SalesRevenue - this.VariableCost - this.FixedCost;
	}
	get TotalCost(): number {
		return this.FixedCost + this.VariableCost;
	}
}


