import { FrameworkElement } from "./FrameworkElement";
import { Brush } from "./Brush";
import { DoubleCollection } from "./DoubleCollection";
import { PenLineCap } from "./PenLineCap";
import { PenLineJoin } from "./PenLineJoin";
import { Base, Type, markType } from "./type";

/**
 * @hidden 
 */
export class Shape extends FrameworkElement {
	static $t: Type = markType(Shape, 'Shape', (<any>FrameworkElement).$);
	constructor() {
		super();
	}
	_fill: Brush = null;
	get fill(): Brush {
		return this._fill;
	}
	set fill(a: Brush) {
		this._fill = a;
	}
	_stroke: Brush = null;
	get stroke(): Brush {
		return this._stroke;
	}
	set stroke(a: Brush) {
		this._stroke = a;
	}
	ab: boolean = false;
	ad: number = 0;
	ai: DoubleCollection = null;
	al: PenLineCap = <PenLineCap>0;
	ak: PenLineCap = <PenLineCap>0;
	am: PenLineJoin = <PenLineJoin>0;
	ac: number = 0;
	aj: PenLineCap = <PenLineCap>0;
}


