import { Base, Type, markType } from "./type";
import { IVisualData, IVisualData_$type } from "./IVisualData";
import { Size } from "./Size";

/**
 * @hidden 
 */
export class SizeData extends Base implements IVisualData {
	static $t: Type = markType(SizeData, 'SizeData', (<any>Base).$, [IVisualData_$type]);
	constructor(a: number, b: number) {
		super();
		this.width = a;
		this.height = b;
	}
	private _width: number = 0;
	get width(): number {
		return this._width;
	}
	set width(a: number) {
		this._width = a;
	}
	private _height: number = 0;
	get height(): number {
		return this._height;
	}
	set height(a: number) {
		this._height = a;
	}
	serialize(): string {
		return "{ width: " + this.width + ", height: " + this.height + "}";
	}
	static b(a: Size): SizeData {
		let b: SizeData = new SizeData(a.width, a.height);
		return b;
	}
	e(): Size {
		let a: Size = new Size(1, this.width, this.height);
		return a;
	}
	static get empty(): SizeData {
		return new SizeData(Number.POSITIVE_INFINITY, Number.POSITIVE_INFINITY);
	}
}


