import { UIElementPropertyAccessor } from "./UIElementPropertyAccessor";
import { Base, enumGetBox, EnumUtil, Type, markType } from "./type";
import { DomWrapper, DomWrapper_$type } from "./dom";
import { Visibility, Visibility_$type } from "./Visibility";

/**
 * @hidden 
 */
export class CssVisibilityPropertyAccessor extends UIElementPropertyAccessor {
	static $t: Type = markType(CssVisibilityPropertyAccessor, 'CssVisibilityPropertyAccessor', (<any>UIElementPropertyAccessor).$);
	b(a: any): any {
		let b = <DomWrapper><any>a;
		if (b.getStyleProperty("display") == "none") {
			return enumGetBox<Visibility>(Visibility_$type, 1);
		}
		return enumGetBox<Visibility>(Visibility_$type, 0);
	}
	c(a: any, b: any): void {
		let c = <DomWrapper><any>a;
		if (EnumUtil.getEnumValue<Visibility>(Visibility_$type, b) == 1) {
			c.hide();
		} else {
			c.show();
		}
	}
}


