import { IgRect } from './IgRect'
import { IgSize } from './IgSize'
import { IgPoint } from './IgPoint'
import { IgDataTemplate } from './IgDataTemplate'
import { IgcHTMLElement } from './igc-html-element'
import { ListSortDirection, ListSortDirection_$type } from "./ListSortDirection";
import { DataSourceSortDescription as DataSourceSortDescription_internal } from "./DataSourceSortDescription";
import { ensureEnum } from "./componentUtil";

export class IgcDataSourceSortDescription
{

protected createImplementation() : DataSourceSortDescription_internal
{
	return new DataSourceSortDescription_internal(0);
}
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : DataSourceSortDescription_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {
	this._implementation = this.createImplementation();
	(<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	/**
	 * Gets or sets the property being sorted.
	*/
	get field() : string {
		return (this.i.f as string);
	}
	set field(v: string) {
		this.i.f = v;
	}
	/**
	 * Gets or sets the direction to sort based on the property.
	*/
	get sortDirection() : ListSortDirection {
		return this.i.c;
	}
	set sortDirection(v: ListSortDirection) {
		this.i.c = ensureEnum<ListSortDirection>(ListSortDirection_$type, v);
	}
	
	    public findByName(name: string): any {
	        
	    if ((this as any).findEphemera) {
	        if (name && name.indexOf("@@e:") == 0) {
	            return (this as any).findEphemera(name);
	        }
	    }
	
	
	        return null;
	    }
	/**
	 * Returns if the SortDescription is equal to another.
	
	* @param other  * The SortDescription to compare to.
	*/
	public equals(other: any) : boolean {
	                        
		let iv = this.i.equals(other);
	                        return (iv);
	}
}
