import { EdgeClipper } from "./EdgeClipper";
import { Point, Base, Point_$type, Type, markType, PointUtil } from "./type";

/**
 * @hidden 
 */
export class LeftClipper extends EdgeClipper {
	static $t: Type = markType(LeftClipper, 'LeftClipper', (<any>EdgeClipper).$);
	m: number = 0;
	protected e(a: Point): boolean {
		return a.x >= this.m;
	}
	k(a: Point, b: Point): Point {
		return <Point>{ $type: Point_$type, x: this.m, y: a.y + (b.y - a.y) * (this.m - a.x) / (b.x - a.x) };
	}
}


