import { IgRect } from './IgRect'
import { IgSize } from './IgSize'
import { IgPoint } from './IgPoint'
import { IgDataTemplate } from './IgDataTemplate'
import { IgcHTMLElement } from './igc-html-element'
import { IgcCaptureImageSettings } from "./igc-capture-image-settings";
import { ImageCapturedEventArgs as ImageCapturedEventArgs_internal } from "./ImageCapturedEventArgs";

export class IgcImageCapturedEventArgs
{
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : ImageCapturedEventArgs_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {									
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	/**
	 * Gets the captured image as Base64.
	*/
	get base64Data() : string {
		return (this.i.base64Data as string);
	}
	/**
	 * Gets the captured image.
	*/
	get image() : any {
		return this.i.image as any;
	}
	/**
	 * Gets the settings used to capture the image.
	*/
	get settings() : IgcCaptureImageSettings {
	                                        const r = this.i.settings;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = new IgcCaptureImageSettings();
	                                            if ((r as any).$type) {
	                                                (e as any)._implementation = r;
	                                            } else {
	                                                if ((e.i as any).setNativeElement) {
	                                                    (e.i as any).setNativeElement(r);
	                                                }
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
}
