import { Base, Type, markType } from "./type";
import { IVisualData, IVisualData_$type } from "./IVisualData";
import { Rect } from "./Rect";

/**
 * @hidden 
 */
export class RectData extends Base implements IVisualData {
	static $t: Type = markType(RectData, 'RectData', (<any>Base).$, [IVisualData_$type]);
	constructor(a: number, b: number, c: number, d: number) {
		super();
		this.left = a;
		this.top = b;
		this.width = c;
		this.height = d;
	}
	private _top: number = 0;
	get top(): number {
		return this._top;
	}
	set top(a: number) {
		this._top = a;
	}
	private _left: number = 0;
	get left(): number {
		return this._left;
	}
	set left(a: number) {
		this._left = a;
	}
	private _width: number = 0;
	get width(): number {
		return this._width;
	}
	set width(a: number) {
		this._width = a;
	}
	private _height: number = 0;
	get height(): number {
		return this._height;
	}
	set height(a: number) {
		this._height = a;
	}
	serialize(): string {
		return "{ top: " + this.top + ", left: " + this.left + ", width: " + this.width + ", height: " + this.height + "}";
	}
	static b(a: Rect): RectData {
		let b: RectData = new RectData(a.left, a.top, a.width, a.height);
		return b;
	}
	h(): Rect {
		let a: Rect = new Rect(0, this.left, this.top, this.width, this.height);
		return a;
	}
	get isEmpty(): boolean {
		return this.width < 0;
	}
	static get empty(): RectData {
		return new RectData(Number.POSITIVE_INFINITY, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY, Number.NEGATIVE_INFINITY);
	}
}


