import { Base, Type, markType } from "./type";
import { IRandomnessGenerator, IRandomnessGenerator_$type } from "./IRandomnessGenerator";
import { Random } from "./Random";

/**
 * @hidden 
 */
export class DefaultRandomnessGenerator extends Base implements IRandomnessGenerator {
	static $t: Type = markType(DefaultRandomnessGenerator, 'DefaultRandomnessGenerator', (<any>Base).$, [IRandomnessGenerator_$type]);
	private a: Random = null;
	constructor(a: Random) {
		super();
		this.a = a;
	}
	next(a: number, b: number): number {
		return this.a.next2(a, b);
	}
	nextDouble(): number {
		return this.a.nextDouble();
	}
}


