import { IgRect } from './IgRect'
import { IgSize } from './IgSize'
import { IgPoint } from './IgPoint'
import { IgDataTemplate } from './IgDataTemplate'
import { IgcHTMLElement } from './igc-html-element'
import { CaptureImageFormat, CaptureImageFormat_$type } from "./CaptureImageFormat";
import { CaptureImageSettings as CaptureImageSettings_internal } from "./CaptureImageSettings";
import { ensureEnum, ensureBool } from "./componentUtil";

export class IgcCaptureImageSettings
{

protected createImplementation() : CaptureImageSettings_internal
{
	return new CaptureImageSettings_internal();
}
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : CaptureImageSettings_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {
	this._implementation = this.createImplementation();
	(<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	get format() : CaptureImageFormat {
		return this.i.a;
	}
	set format(v: CaptureImageFormat) {
		this.i.a = ensureEnum<CaptureImageFormat>(CaptureImageFormat_$type, v);
	}
	get addToClipboard() : boolean {
		return (this.i.b as boolean);
	}
	set addToClipboard(v: boolean) {
		this.i.b = ensureBool(v);
	}
	
	    public findByName(name: string): any {
	        
	    if ((this as any).findEphemera) {
	        if (name && name.indexOf("@@e:") == 0) {
	            return (this as any).findEphemera(name);
	        }
	    }
	
	
	        return null;
	    }
}
