import { Shape } from "./Shape";
import { Base, Type, markType } from "./type";

/**
 * @hidden 
 */
export class Line extends Shape {
	static $t: Type = markType(Line, 'Line', (<any>Shape).$);
	constructor() {
		super();
		this.an = 0;
		this.ao = 0;
		this.ap = 0;
		this.aq = 0;
	}
	an: number = 0;
	ao: number = 0;
	ap: number = 0;
	aq: number = 0;
}


