import { ToolActionDescription } from "./ToolActionDescription";
import { Description } from "./Description";
import { Base, Type, markType } from "./type";

/**
 * @hidden 
 */
export class ToolActionButtonDescription extends ToolActionDescription {
	static $t: Type = markType(ToolActionButtonDescription, 'ToolActionButtonDescription', (<any>ToolActionDescription).$);
	protected get_type(): string {
		return "ToolActionButton";
	}
	constructor() {
		super();
	}
	private dy: string = null;
	get displayType(): string {
		return this.dy;
	}
	set displayType(a: string) {
		this.dy = a;
		this.j("DisplayType");
	}
	private dw: number = 0;
	get cornerRadius(): number {
		return this.dw;
	}
	set cornerRadius(a: number) {
		this.dw = a;
		this.j("CornerRadius");
	}
}


