import { Base, Type, getBoxIfEnum, markType } from "./type";
import { AsyncVirtualDataTask } from "./AsyncVirtualDataTask";

/**
 * @hidden 
 */
export class AsyncVirtualDataTaskCompletionSource<T> extends Base {
	static $t: Type = markType(AsyncVirtualDataTaskCompletionSource, 'AsyncVirtualDataTaskCompletionSource');
	protected $t: Type = null;
	constructor($t: Type) {
		super();
		this.$t = $t;
		this.$type = this.$type.specialize(this.$t);
	}
	private _task: AsyncVirtualDataTask = null;
	get task(): AsyncVirtualDataTask {
		return this._task;
	}
	set task(a: AsyncVirtualDataTask) {
		this._task = a;
	}
	setResult(a: T): void {
		this.task.result = getBoxIfEnum<T>(this.$t, a);
		this.task.isCompleted = true;
	}
}


