import { IgRect } from './IgRect'
import { IgSize } from './IgSize'
import { IgPoint } from './IgPoint'
import { IgDataTemplate } from './IgDataTemplate'
import { IgcHTMLElement } from './igc-html-element'
import { DoubleValueChangedEventArgs as DoubleValueChangedEventArgs_internal } from "./DoubleValueChangedEventArgs";

/**
 * Provides data for double value change events.
*/
export class IgcDoubleValueChangedEventArgs
{
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : DoubleValueChangedEventArgs_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {									
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	/**
	 * Gets the value before the change.
	*/
	get oldValue() : number {
		return (this.i.oldValue as number);
	}
	set oldValue(v: number) {
		this.i.oldValue = +v;
	}
	/**
	 * Gets the new value.
	*/
	get newValue() : number {
		return (this.i.newValue as number);
	}
	set newValue(v: number) {
		this.i.newValue = +v;
	}
}
