import { TypeRegistrar } from 'igniteui-core/type';
import { html, render, TemplateFunction } from 'igniteui-core/template';
import { IgcHTMLElement } from 'igniteui-core/igc-html-element';

export class IgcSimpleDefaultTooltipComponent extends IgcHTMLElement {
    
    public tooltip: TemplateFunction;

    labelText:any;

    constructor() {
        super();

        this.tooltip = (context: any) => context ? html`
    <div class='ui-simple-default-tooltip-content'>
        <span  style="white-space: nowrap;font-weight: bold;" >${this.getLabel(context)}</span>
    </div>
` : html``;
    }

    ensureDefaultTooltip(gauge: any) {
        if (gauge.showToolTip) {
            gauge.tooltipTemplate = this.tooltip;
        } else {
            gauge.tooltipTemplate = null;
        }
    }

    getLabel(context: any) {
        if (context.itemName == null) {
            let label = context.label.split(":");
            return label.length < 2 ? context.label : label[1].trim();
        }
        return context.label;
    }
    
    onContentReady: () => void;

    render(context: any): void {
        if (this.tooltip) {
            let templ = this.tooltip(context);

            render(templ, this);
        }
    }

    connectedCallback() {
            
        if (this.onContentReady) {
            this.onContentReady();
        }
    }

    protected static _registered: boolean = false;
    public static htmlTagName: string = "igc-simple-default-tooltip";
    static register(): void {
        if (!IgcSimpleDefaultTooltipComponent._registered) {
            IgcSimpleDefaultTooltipComponent._registered = true;
            if (window.customElements) {
                window.customElements.define(IgcSimpleDefaultTooltipComponent.htmlTagName, IgcSimpleDefaultTooltipComponent);
            } else {
                (<any>document).registerElement(IgcSimpleDefaultTooltipComponent.htmlTagName, IgcSimpleDefaultTooltipComponent);
            }
            TypeRegistrar.registerCons("IgcSimpleDefaultTooltipComponent", IgcSimpleDefaultTooltipComponent);
        }
    }
}