import { Base, Type, markType } from "./type";
import { DataSourceSummaryOperand } from "./DataSourceSummaryOperand";

/**
 * @hidden 
 */
export class SummaryParser extends Base {
	static $t: Type = markType(SummaryParser, 'SummaryParser');
	a(a: string, b: (arg1: string, arg2: DataSourceSummaryOperand, arg3: string) => void): void {
		if (a == null) {
			return;
		}
		let c = a.split(',');
		for (let d: number = 0; d < c.length; d++) {
			let e = c[d].trim();
			let f: string = "";
			let g: number = 0;
			for (g = 0; g < e.length; g++) {
				let h: string = e.charAt(g);
				if (h != '(') {
					f += h;
				} else {
					break;
				}
			}
			if (g == e.length) {
				continue;
			}
			f = f.trim().toLowerCase();
			let i: DataSourceSummaryOperand = 4;
			switch (f) {
				case "avg":
				i = 3;
				break;

				case "sum":
				i = 2;
				break;

				case "min":
				i = 0;
				break;

				case "max":
				i = 1;
				break;

				case "count":
				i = 4;
				break;

				default: continue;
			}

			g++;
			let j: string = "";
			for (; g < e.length; g++) {
				let k: string = e.charAt(g);
				if (k != ')') {
					j += k;
				} else {
					break;
				}
			}
			if (j.length == 0) {
				continue;
			}
			if (e.charAt(g) != ')') {
				continue;
			}
			g++;
			let l: string = null;
			if (g < e.length) {
				if (e.charAt(g) != ' ') {
					continue;
				}
				g++;
				if (e.substr(g, 2) != "as") {
					continue;
				}
				g += 2;
				if (e.charAt(g) != ' ') {
					continue;
				}
				g++;
				l = e.substr(g, e.length - g);
			}
			if (b != null) {
				b(j, i, l);
			}
		}
	}
}


