import { UIElementPropertyAccessor } from "./UIElementPropertyAccessor";
import { Base, enumGetBox, EnumUtil, Type, markType } from "./type";
import { DomWrapper, DomWrapper_$type } from "./dom";
import { NativeUICursor, NativeUICursor_$type } from "./NativeUICursor";

/**
 * @hidden 
 */
export class CssCursorPropertyAccessor extends UIElementPropertyAccessor {
	static $t: Type = markType(CssCursorPropertyAccessor, 'CssCursorPropertyAccessor', (<any>UIElementPropertyAccessor).$);
	b(a: any): any {
		let b = <DomWrapper><any>a;
		let c = b.getStyleProperty("cursor");
		if (c != null) {
			switch (c.toLowerCase()) {
				case "pointer": return enumGetBox<NativeUICursor>(NativeUICursor_$type, 1);
			}

		}
		return enumGetBox<NativeUICursor>(NativeUICursor_$type, 0);
	}
	c(a: any, b: any): void {
		let c = <DomWrapper><any>a;
		switch (EnumUtil.getEnumValue<NativeUICursor>(NativeUICursor_$type, b)) {
			case 1:
			c.setStyleProperty("cursor", "pointer");
			break;

			case 0:
			c.setStyleProperty("cursor", "auto");
			break;

		}

	}
}


