import { Base, Type, markType } from "./type";

/**
 * @hidden 
 */
export class PointTester extends Base {
	static $t: Type = markType(PointTester, 'PointTester');
	c(a: number, b: number, c: number, d: number, e: number, f: number, g: number, h: number): boolean {
		let i: number = Math.abs(d - f);
		let j: number = Math.abs(f - h);
		let k: number = 0;
		let l: number = 0;
		if (i == 0 && j == 0) {
			return false;
		}
		if (i == 0 && j != 0) {
			k = (e + c) / 2;
			l = (-(g - e) / (h - f)) * (k - ((e + g) / 2)) + ((f + h) / 2);
		}
		if (i != 0 && j == 0) {
			k = (g + e) / 2;
			l = (-(e - c) / (f - d)) * (k - ((c + e) / 2)) + ((d + f) / 2);
		}
		if (i != 0 && j != 0) {
			let m: number = -(e - c) / (f - d);
			let n: number = -(g - e) / (h - f);
			let o: number = (c + e) / 2;
			let p: number = (e + g) / 2;
			let q: number = (d + f) / 2;
			let r: number = (f + h) / 2;
			k = (m * o - n * p + r - q) / (m - n);
			l = i > j ? m * (k - o) + q : n * (k - p) + r;
		}
		let s: number = e - k;
		let t: number = f - l;
		let u: number = s * s + t * t;
		s = a - k;
		t = b - l;
		let v: number = s * s + t * t;
		this.b = v <= u;
		this.a = k < a && ((a - k) * (a - k)) > u;
		return true;
	}
	a: boolean = false;
	b: boolean = false;
}


