import { Base, Type, markType } from "./type";

/**
 * @hidden 
 */
export class Thickness extends Base {
	static $t: Type = markType(Thickness, 'Thickness');
	constructor(a: number, b: number);
	constructor(a: number, b: number, c: number, d: number, e: number);
	constructor(a: number);
	constructor(a: number, ..._rest: any[]);
	constructor(a: number, ..._rest: any[]) {
		super();
		a = (a == void 0) ? 0 : a;
		switch (a) {
			case 0:
			{
				let c: number = <number>_rest[0];
				this.bottom = this.left = this.right = this.top = c;
			}
			break;

			case 1:
			{
				let c: number = <number>_rest[0];
				let d: number = <number>_rest[1];
				let e: number = <number>_rest[2];
				let f: number = <number>_rest[3];
				this.left = c;
				this.top = d;
				this.right = e;
				this.bottom = f;
			}
			break;

			case 2:
			{
				this.bottom = NaN;
				this.left = NaN;
				this.right = NaN;
				this.top = NaN;
			}
			break;

		}

	}
	private _bottom: number = 0;
	get bottom(): number {
		return this._bottom;
	}
	set bottom(a: number) {
		this._bottom = a;
	}
	private _left: number = 0;
	get left(): number {
		return this._left;
	}
	set left(a: number) {
		this._left = a;
	}
	private _right: number = 0;
	get right(): number {
		return this._right;
	}
	set right(a: number) {
		this._right = a;
	}
	private _top: number = 0;
	get top(): number {
		return this._top;
	}
	set top(a: number) {
		this._top = a;
	}
	a(a: Thickness): boolean {
		return this.bottom == a.bottom && this.top == a.top && this.left == a.left && this.right == a.right;
	}
	toString(): string {
		let a = this.left.toString() + "," + this.top.toString() + "," + this.right.toString() + "," + this.bottom.toString();
		return a;
	}
}


