import { ScatterBaseDescription } from "./ScatterBaseDescription";
import { Description } from "./Description";
import { Base, Type, markType } from "./type";

/**
 * @hidden 
 */
export class ScatterSplineSeriesDescription extends ScatterBaseDescription {
	static $t: Type = markType(ScatterSplineSeriesDescription, 'ScatterSplineSeriesDescription', (<any>ScatterBaseDescription).$);
	protected get_type(): string {
		return "ScatterSplineSeries";
	}
	constructor() {
		super();
	}
	private he: number = 0;
	get stiffness(): number {
		return this.he;
	}
	set stiffness(a: number) {
		this.he = a;
		this.j("Stiffness");
	}
}


