import { TypeRegistrar } from './type';
import { IgcHTMLElement } from './igc-html-element';

export class IgcChildContentComponent extends IgcHTMLElement {
    constructor() {
        super();

        
    }

    private _display: string = "inline-block";
    private _flexDirection: string = "row";
    private _alignItems: string = "center";

    public get display() {
        return this._display;
    }
    public set display(value: string) {
        this._display = value;
        this.style.display = value;
    }

    public get flexDirection() {
        return this._flexDirection;
    }
    public set flexDirection(value: string) {
        this._flexDirection = value;
        this.style.flexDirection = value;
    }

    public get alignItems() {
        return this._alignItems;
    }
    public set alignItems(value: string) {
        this._alignItems = value;
        this.style.alignItems = value;
    }

    public onChildrenChanged(children: any[]) {
        for (var i = 0; i < children.length; i++) {
            var child = children[i];
            child.remove();
            this.appendChild(child);
        }
    }

    connectedCallback() {
        this.attachedCallback();
    }

    private _attached: boolean = false;
    attachedCallback() {
        this._attached = true;
    }
   
    public static htmlTagName: string = "igc-child-content";
    protected static _registered: boolean = false;
    static register(): void {
        if (!IgcChildContentComponent._registered) {
            IgcChildContentComponent._registered = true;
            if (window.customElements) {
                window.customElements.define(IgcChildContentComponent.htmlTagName, IgcChildContentComponent);
            } else {
                (<any>document).registerElement(IgcChildContentComponent.htmlTagName, IgcChildContentComponent);
            }
            TypeRegistrar.registerCons("IgcChildContentComponent", IgcChildContentComponent);
        }
    }
}