import { IgRect } from './IgRect'
import { IgSize } from './IgSize'
import { IgPoint } from './IgPoint'
import { IgDataTemplate } from './IgDataTemplate'
import { IgcHTMLElement } from './igc-html-element'
import { ModifierKeys, ModifierKeys_$type } from "./ModifierKeys";
import { KeyEventArgs as KeyEventArgs_internal } from "./KeyEventArgs";
import { ensureBool, ensureEnum } from "./componentUtil";

/**
 * Event args for KeyUp and KeyDown events.
*/
export class IgcKeyEventArgs
{
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : KeyEventArgs_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {									
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	get originalEvent() : any {
		return this.i.originalEvent as any;
	}
	/**
	 * Gets a value indicating whether the ALT key was pressed.
	*/
	get alt() : boolean {
		return (this.i.alt as boolean);
	}
	/**
	 * Gets a value indicating whether the CTRL key was pressed.
	*/
	get ctrl() : boolean {
		return (this.i.ctrl as boolean);
	}
	/**
	 * Gets the keyboard code for a KeyDown or KeyUp event.
	*/
	get keyCode() : number {
		return (this.i.keyCode as number);
	}
	/**
	 * Gets the modifier flags for a KeyDown or KeyUp event. 
	 * The flags indicate which combination of CTRL, SHIFT, and ALT keys was pressed.
	*/
	get modifiers() : ModifierKeys {
		return this.i.modifiers;
	}
	/**
	 * Gets a value indicating whether the SHIFT key was pressed.
	*/
	get shift() : boolean {
		return (this.i.shift as boolean);
	}
	/**
	 * Gets whether the PreventDefault method was called.
	*/
	get defaultPrevented() : boolean {
		return (this.i.defaultPrevented as boolean);
	}
	/**
	 * Tells the user agent that if the event does not get explicitly handled, its default action should not be taken as it normally would be.
	
	*/
	public preventDefault() {
		this.i.preventDefault();
	}
	/**
	 * Prevent the event from bubbling up.
	
	*/
	public stopPropagation() {
		this.i.stopPropagation();
	}
}
