import { Base, Type, markType } from "./type";
import { BinaryUtil } from "./binary";

/**
 * @hidden 
 */
export class BinaryFileDownloader extends Base {
	static $t: Type = markType(BinaryFileDownloader, 'BinaryFileDownloader');
	static a(uri_: string, callback_: (arg1: string) => void, errorCallback_: (arg1: string) => void): void {
		BinaryUtil.getBinary(uri_, callback_, errorCallback_);
	}
}


