import { BrushScaleDescription } from "./BrushScaleDescription";
import { Description } from "./Description";
import { Base, Type, markType } from "./type";

/**
 * @hidden 
 */
export class CustomPaletteBrushScaleDescription extends BrushScaleDescription {
	static $t: Type = markType(CustomPaletteBrushScaleDescription, 'CustomPaletteBrushScaleDescription', (<any>BrushScaleDescription).$);
	protected get_type(): string {
		return "CustomPaletteBrushScale";
	}
	constructor() {
		super();
	}
	private p: string = null;
	get brushSelectionMode(): string {
		return this.p;
	}
	set brushSelectionMode(a: string) {
		this.p = a;
		this.j("BrushSelectionMode");
	}
}


