import { EdgeClipper } from "./EdgeClipper";
import { Point, Base, Point_$type, Type, markType, PointUtil } from "./type";

/**
 * @hidden 
 */
export class BottomClipper extends EdgeClipper {
	static $t: Type = markType(BottomClipper, 'BottomClipper', (<any>EdgeClipper).$);
	m: number = 0;
	protected e(a: Point): boolean {
		return a.y <= this.m;
	}
	k(a: Point, b: Point): Point {
		return <Point>{ $type: Point_$type, x: a.x + (b.x - a.x) * (this.m - a.y) / (b.y - a.y), y: this.m };
	}
}


