import { Base, Point, Point_$type, Type, markType, PointUtil } from "./type";
import { LineEquation } from "./LineEquation";

/**
 * @hidden 
 */
export class Compute extends Base {
	static $t: Type = markType(Compute, 'Compute');
	static b(a: Point, b: Point, c: Point, d: Point): Point {
		return Compute.a(new LineEquation(1, a, b), new LineEquation(1, c, d));
	}
	static a(a: LineEquation, b: LineEquation): Point {
		let c = <Point>{ $type: Point_$type, x: NaN, y: NaN };
		if (a.a && b.a) {
			return c;
		}
		if (a.a || b.a) {
			let d = b.a ? b : a;
			let e = b.a ? a : b;
			let f = (d.g.x - e.g.x) * (e.f.y - e.g.y) / (e.f.x - e.g.x) + e.g.y;
			let g = a.a ? a.g.x : b.g.x;
			return <Point>{ $type: Point_$type, x: g, y: f };
		}
		let h = a.b * b.c - b.b * a.c;
		let i = Math.abs(h - 0) > 9.9999997473787516E-05;
		if (i) {
			let j = (b.c * a.d - a.c * b.d) / h;
			let k = (a.b * b.d - b.b * a.d) / h;
			c = <Point>{ $type: Point_$type, x: j, y: k };
		}
		return c;
	}
}


