import { PathSegment } from "./PathSegment";
import { PointCollection } from "./PointCollection";
import { PathSegmentType } from "./PathSegmentType";
import { Base, Type, markType } from "./type";

/**
 * @hidden 
 */
export class PolyBezierSegment extends PathSegment {
	static $t: Type = markType(PolyBezierSegment, 'PolyBezierSegment', (<any>PathSegment).$);
	constructor() {
		super();
		this.b = new PointCollection(0);
	}
	b: PointCollection = null;
	protected get_a(): PathSegmentType {
		return 2;
	}
	get a(): PathSegmentType {
		return this.get_a();
	}
}


