import { IgRect } from './IgRect'
import { IgSize } from './IgSize'
import { IgPoint } from './IgPoint'
import { IgDataTemplate } from './IgDataTemplate'
import { IgcHTMLElement } from './igc-html-element'
import { PageRequestedEventArgs as PageRequestedEventArgs_internal } from "./PageRequestedEventArgs";
import { ensureBool } from "./componentUtil";

/**
 * Information about the requested page.
*/
export class IgcPageRequestedEventArgs
{

protected createImplementation() : PageRequestedEventArgs_internal
{
	return new PageRequestedEventArgs_internal();
}
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : PageRequestedEventArgs_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {
	this._implementation = this.createImplementation();
	(<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	/**
	 * The data source is requesting the schema for the data.
	*/
	get isSchemaRequest() : boolean {
		return (this.i.a as boolean);
	}
	set isSchemaRequest(v: boolean) {
		this.i.a = ensureBool(v);
	}
	/**
	 * The unique ID for the page request.
	*/
	get requestId() : number {
		return (this.i.e as number);
	}
	set requestId(v: number) {
		this.i.e = +v;
	}
	/**
	 * The Unique ID for the data source making the request.
	*/
	get dataSourceId() : number {
		return (this.i.b as number);
	}
	set dataSourceId(v: number) {
		this.i.b = +v;
	}
	/**
	 * The page index being requested.
	*/
	get pageIndex() : number {
		return (this.i.c as number);
	}
	set pageIndex(v: number) {
		this.i.c = +v;
	}
	/**
	 * The page size being requested.
	*/
	get pageSize() : number {
		return (this.i.d as number);
	}
	set pageSize(v: number) {
		this.i.d = +v;
	}
}
