import { Enum, ValueType, markEnum, Type } from "./type";

/**
 * Describes mode for displaying units after series values in the data legend.
 */
export enum DataLegendUnitsMode {
	/**
	 * Specifies automatic visibility of units based on series type
	 */
	Auto = 0,
	/**
	 * Specifies always visible units after series values
	 */
	Visible = 1,
	/**
	 * Specifies hidden units after series values
	 */
	Hidden = 2
}

/**
 * @hidden 
 */
export let DataLegendUnitsMode_$type = markEnum('DataLegendUnitsMode', 'Auto,0|Visible,1|Hidden,2');


